import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.D31cdF9L.js";var i=JSON.parse(`{"title":"Supported Assets","description":"","frontmatter":{},"headers":[],"relativePath":"reference/supported-assets.md","filePath":"reference/supported-assets.md"}`),a={name:`reference/supported-assets.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="supported-assets" tabindex="-1">Supported Assets <a class="header-anchor" href="#supported-assets" aria-label="Permalink to “Supported Assets”">​</a></h1><p>GraphScribe exports Blueprint assets anything that can contain functions and graphs plus DataAssets.</p><h2 id="what-can-be-exported" tabindex="-1">What can be exported <a class="header-anchor" href="#what-can-be-exported" aria-label="Permalink to “What can be exported”">​</a></h2><table tabindex="0"><thead><tr><th>Asset type</th><th>Exported content</th></tr></thead><tbody><tr><td><strong>Blueprint</strong></td><td>Variables, functions, macros, event graphs, delegates, class references</td></tr><tr><td><strong>Widget Blueprint</strong></td><td>Everything in a Blueprint, plus the widget tree and animation names</td></tr><tr><td><strong>DataAsset</strong></td><td>A dump of its properties and default values, plus any class references it points to</td></tr></tbody></table><p>All three export in all four formats (Markdown, Mermaid, JSON, Graphify).</p><p>Normal, const, and level Blueprints are supported, including <code>UBlueprint</code> subclasses such as gameplay-ability Blueprints.</p><h2 id="what-is-always-included" tabindex="-1">What is always included <a class="header-anchor" href="#what-is-always-included" aria-label="Permalink to “What is always included”">​</a></h2><ul><li><strong>Variables</strong> including default values.</li><li><strong>DataAsset / CDO property dumps</strong> the actual property defaults stored on the asset. Container elements (array/set/map entries) are expanded and dumped, the scope of inherited content follows the <a href="/GraphScribe-Documentation/guide/settings.html">Property Dump Mode</a>.</li><li><strong>Class references</strong> <code>TSubclassOf</code>, <code>TSoftClassPtr</code>, and references inside nested containers are walked and surfaced as <code>cls:</code> nodes in Graphify (and in the Markdown Class References section).</li><li><strong>Delegates</strong> with signature parameters and defaults.</li><li><strong>Widget hierarchy</strong> for Widget Blueprints.</li></ul><h2 id="what-is-never-exported" tabindex="-1">What is never exported <a class="header-anchor" href="#what-is-never-exported" aria-label="Permalink to “What is never exported”">​</a></h2><ul><li><strong>DataTables</strong> they can be exported as <code>csv</code> or <code>json</code> natively, so GraphScribe never gathers them.</li><li><strong>Blueprint comment boxes</strong> skipped, they are not collected into the output.</li><li><strong>Selection exports</strong> deliberately omit <strong>variables, widget trees, and class references</strong>: a snippet is meant to show a piece of logic, not the whole asset.</li></ul>`,10)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};